WebLink.url:
var varUrl = "";
var  area = '{!Case.Area__c}';
if( area  =='South')
varUrl= 'http://imsharepoint/csg/hr/training/csort/Document%20Library/Escalation%20Lists/Southern%20Area%20Escalation.xls';
else if (area == 'EASTERN')
varUrl = 'http://imsharepoint/csg/hr/training/csort/Document Library/Escalation Lists/Eastern Area Escalation.xls';
else if (area  == 'CANADA')
varUrl  = 'http://imsharepoint/csg/hr/training/csort/Document Library/Escalation Lists/Canada Area Escalation.xls';
else if (area == 'CENTRAL')
varUrl  = 'http://imsharepoint/csg/hr/training/csort/Document%20Library/Escalation%20Lists/Central%20Area%20Escalation.xls';
else if (area == 'WESTERN')
varUrl  ='http://imsharepoint/csg/hr/training/csort/Document%20Library/Escalation%20Lists/Western%20Area%20Escalation.xls';


if(varUrl  !='')
window.open(varUrl);
